GEMINI_URL="https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key={}"

def _gemini_raw(prompt,history=None,system="",max_tokens=1800):
    key=st.session_state.gemini_key
    if not key: return ""
    url=GEMINI_URL.format(key)
    contents=list(history or [])+[{"role":"user","parts":[{"text":prompt}]}]
    body={"contents":contents,"generationConfig":{"temperature":0.6,"maxOutputTokens":max_tokens}}
    if system: body["systemInstruction"]={"parts":[{"text":system}]}
    try:
        r=requests.post(url,json=body,timeout=35); r.raise_for_status()
        return r.json()["candidates"][0]["content"]["parts"][0]["text"]
    except Exception as e:
        try: return f"ERROR:{r.json().get('error',{}).get('message',str(e))}"
        except: return f"ERROR:{e}"

HEALTH_KW={"health","medicine","medical","clinical","disease","drug","nutrition","epidemi","public health","dentist","dental","oral","cancer","pharmacy","covid","mental","nursing","patient","hospital","vaccine","global health"}
