def build_explain_prompt(title, url, summary, mode="Explain", subtype="Conceptual"):
    mode_instr = {
        "Explain": f"Explain this article ({subtype} perspective)",
        "Research": "Provide a deep research analysis of this article",
        "Digest": "Write a concise digest of this article for busy researchers",
        "Critical Lens": "Critically analyse this article — challenge assumptions, find gaps",
        "Policy Lens": "Analyse the policy implications of this article",
    }.get(mode, "Explain this article")
    return f"""{mode_instr}.\nTitle: "{title}"\n{f"URL: {url}" if url else ""}\n{f"Snippet: {summary[:400]}" if summary else ""}\n\n## 📌 What Is This?\n## 🕰️ Background\n## 📊 Current Evidence\n## 🔮 What's Next\n## 💡 Why It Matters\n\nEnd with exactly: SUGGESTIONS: q1? | q2? | q3?"""

def parse_explanation(text):
    followups=[]
    if "SUGGESTIONS:" in text:
        parts=text.split("SUGGESTIONS:"); text=parts[0].strip()
        followups=[q.strip() for q in parts[1].split("|") if "?" in q][:3]
    sections,label,lines=[],None,[]
    for line in text.split("\n"):
        if line.startswith("## "):
            if label: sections.append((label,"\n".join(lines).strip()))
            label,lines=line[3:].strip(),[]
        else: lines.append(line)
    if label: sections.append((label,"\n".join(lines).strip()))
    return sections,followups

def render_section_content(content):
    lines=content.split("\n"); buf,in_list=[],False
    for line in lines:
        line=line.strip(); is_b=re.match(r'^[\-\*•]\s+',line); is_n=re.match(r'^\d+\.\s+',line)
        clean=re.sub(r'^[\-\*•\d\.]\s+','',line)
        if is_b or is_n:
            if not in_list:
                if buf: st.markdown(" ".join(buf)); buf=[]
                in_list=True
            buf.append(f"- {clean}")
        else:
            if in_list: st.markdown("\n".join(buf)); buf=[]; in_list=False
            if clean: buf.append(clean)
    if buf: st.markdown("\n".join(buf) if in_list else " ".join(buf))

