def handle_oauth_callback():
    code = st.query_params.get("code")
    if code and not st.session_state.user:
        try:
            sess = supabase.auth.exchange_code_for_session({"auth_code": code})
            st.session_state.user = sess.user
            st.query_params.clear()
            _load_user_data_from_db(sess.user.id)
        except Exception as e:
            st.error(f"Login failed: {e}")

def _load_user_data_from_db(user_id):
    try:
        row = svc.table("user_areas").select("areas,subtopics").eq("user_id", user_id).maybe_single().execute()
        sub_row = svc.table("subscriptions").select("*").eq("user_id", user_id).maybe_single().execute()
        if row.data:
            areas = row.data.get("areas") or []
            subs = row.data.get("subtopics") or {}
            if areas:
                st.session_state.selected_areas = areas
                st.session_state.topics = list(dict.fromkeys(areas))
                st.session_state.active_topic = st.session_state.topics[0]
            if subs:
                st.session_state.subtopics = subs
        if sub_row.data:
            st.session_state.subscription = sub_row.data
        if st.session_state.topics:
            st.session_state.onboarded = True
    except Exception:
        pass

def save_user_areas_to_db():
    if not st.session_state.user:
        return
    try:
        svc.table("user_areas").upsert({
            "user_id": st.session_state.user.id,
            "areas": st.session_state.selected_areas,
            "subtopics": st.session_state.subtopics,
        }).execute()
    except Exception:
        pass

def get_tier():
    sub = st.session_state.subscription
    if not sub: return "free"
    status = sub.get("status", "free")
    if status == "premium": return "premium"
    if status == "trial":
        trial_ends = sub.get("trial_ends_at")
        if trial_ends:
            try:
                ends = dt.datetime.fromisoformat(trial_ends.replace("Z", "+00:00"))
                if dt.datetime.now(dt.timezone.utc) < ends: return "trial"
            except Exception: pass
    return "free"

def can_use_ai():
    tier = get_tier()
    if tier == "premium": return True, None
    if tier == "trial":
        sub = st.session_state.subscription or {}
        used = sub.get("ai_calls_used", 0)
        limit = sub.get("ai_calls_limit", 10)
        if used < limit: return True, None
        return False, f"Trial limit reached ({limit} calls). Upgrade to continue."
    return False, "AI features require a subscription. Upgrade for ₹299/month."

def increment_ai_calls():
    if get_tier() != "trial" or not st.session_state.user: return
    try:
        sub = st.session_state.subscription or {}
        new_count = sub.get("ai_calls_used", 0) + 1
        svc.table("subscriptions").update({"ai_calls_used": new_count}).eq("user_id", st.session_state.user.id).execute()
        if st.session_state.subscription:
            st.session_state.subscription["ai_calls_used"] = new_count
    except Exception: pass

def max_areas_for_tier(): return 999 if get_tier() in ("trial", "premium") else 2

def tier_badge_html():
    tier = get_tier()
    if tier == "premium": return '<div class="owl-badge">✦ OpenAI · Premium</div>'
    if tier == "trial":
        sub = st.session_state.subscription or {}
        used = sub.get("ai_calls_used", 0); limit = sub.get("ai_calls_limit", 10)
        return f'<div class="owl-badge-trial">✦ Trial · {limit - used} calls left</div>'
    return '<div class="owl-badge-free">✦ Free Plan</div>'

